//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_Help::Draw()
{
	if (!m_isInitialized) return;

	IVideoDriver *driver = __IRR_DRIVER();	

	m_pageManager->SetActiveCamera( true );

	DrawBackground();

	// Daw controls
	//-------------------------------
	VisualControls_Draw();
	
	m_pageManager->PrepareScene( true );

	driver->endScene2D();

	if ( !m_firstDraw ) 
		__IRR_SCENE()->drawAll( );

	driver->beginScene2D();
	
	if ( m_isIngame ) 
		m_pageManager->SetActiveCamera( false );
	m_firstDraw = false; 
}

void Menu_Help::ResetGraphics()
{
	m_pageManager->SetActiveCamera( false );
	m_pageManager->PrepareScene( false );
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_Help::Update( float dt )
{
	if( !m_isInitialized )
		return;

	m_arrowLeft->SetVisible( m_currentPane->GetCurrentCol() > 0 );
	m_arrowRight->SetVisible( m_currentPane->GetCurrentCol() < m_currentPane->GetCols() - 1 );

	if (m_TW_pages->IsActive())
	{
		int x, y;
		m_TW_pages->GetTouchPos_Current(x, y);

		int pages = m_currentPane->GetCols();
		int x1 = GAME_SCREEN_W2 - pages * k_pagelist_w / 2;
		int x2 = GAME_SCREEN_W2 + pages * k_pagelist_w / 2;

		if (x >= x1 && x <= x2)
		{
			int page = (x - x1) / k_pagelist_w;
			m_currentPane->GoToCol(page);
		}
	}

	IMenu::Update( dt );	

	if ( IsOnFocus() )
		m_pageManager->Update( dt );

	
}

