void Menu_Help::VisualControlDoAction( IVisualControl* visual_control, int action_id )
{
	switch ( action_id ) 
	{
	case action_back:
		{
			Transition_Start( transition_hide, action_back_trans );
		}
		break;
	case action_back_trans:
		{
			if ( !m_isIngame ) 
				GetParent()->SubMenu_Change( "Menu_Info" );
			else 
				GetParent()->SubMenu_Change( "Menu_Ingame_Help" );
		}		
		break;
	case action_left:
		{
		}
		break;
	case action_left_trans:
		{
		}
		break;
	case action_right:
		{
		}
		break;
	case action_right_trans:
		{
		}
		break;
	};

}

