PageManager::PageManager()
{
	m_images = NULL;
	m_camera = NULL; 
	m_light = NULL;
	m_oldCamera = NULL;
	m_pane = NULL;
	m_enemiesPane = NULL;
	m_spellsPane = NULL;

	m_rootNode = NULL;
	m_currentBookType = MenuHelp_NotSet;

}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
PageManager::~PageManager()
{
	if ( m_light ) 
	{
		m_light->remove();
	}

	if ( m_camera ) 
	{
		m_camera->remove();
	}
	
	SAFE_DEL ( m_images ); 
	
	for ( int i = 0; i< m_spellsBook.size() ; i++ )
	{
		SAFE_DEL ( m_spellsBook[i] ); 
	}
	m_spellsBook.clear();

	for ( int i = 0; i< m_enemiesBook.size() ; i++ )
	{
		SAFE_DEL ( m_enemiesBook[i] ); 
	}		
	m_enemiesBook.clear();

	m_pane = NULL;
	m_enemiesPane = NULL;
	m_spellsPane = NULL;
	m_oldCamera = NULL;
	m_light = NULL;
	m_camera = NULL;

	if ( m_rootNode ) 
	{
		m_rootNode->remove();
	}

	m_rootNode = NULL;
}
