//---------------------------------------------------------------------------------------------------------

void PageManager::PrepareScene( bool hideAll ) 
{
	//hideAll = false;
	ISceneNode *sceneRoot = __IRR_SCENE()->getRootSceneNode();
	list<ISceneNode *>::ConstIterator iter;
	list<ISceneNode *> children = sceneRoot->getChildren();

	for ( iter = children.begin(); iter !=  children.end() ; ++iter )
	{
		if ( (*iter) != m_rootNode ) 
		{
			(*iter)->setVisible( !hideAll );
		}	
	}

	m_rootNode->setVisible( hideAll );		
}
