void PageManager::SetActiveCamera( bool activate )
{
	if ( activate )
	{			
		__IRR_SCENE()->setActiveCamera( m_camera );			
	}	
	else
	{
		__IRR_SCENE()->setActiveCamera( m_oldCamera );	
		m_oldCamera->render();
	}	
}
