void PageManager::CreateHelpers()
{
	m_rootNode = __IRR_SCENE()->addEmptySceneNode();

	const v3f k_weapon_camera_pos = v3f( 0 , 0, -30 );	
	m_camera = __IRR_SCENE()->addCameraSceneNode( m_rootNode );		
	// Camera
	matrix4 projection;
#if defined(OS_WIN32) || defined(OS_LINUX)
	projection.buildProjectionMatrixOrtho( 480.0f, 320.0f, 1, 150 );
#else
	projection.buildProjectionMatrixOrtho( 320.0f, 480.0f, 1, 150 );
#endif	
	m_camera->setProjectionMatrix( projection, true );
	m_camera->setTarget( v3f( 0 , 0, 0 ) );
	m_camera->setPosition( k_weapon_camera_pos );

	m_light = __IRR_SCENE()->addLightSceneNode( m_rootNode );
	// Light
	m_light->getLightData().Type = ELT_AMBIENT;
	m_light->getLightData().AmbientColor = SColorf( 1,1,1,1 );
	m_light->getLightData().DiffuseColor = SColorf( 0,0,0,0 );

	m_rootNode->setVisible( false );

}
