void PageManager::Draw( ASprite *sprite )
{
	
	int num_pages = GetCurrentBook().size();
	int x1 = GAME_SCREEN_W2 - num_pages * k_pagelist_w / 2;
	int x2 = GAME_SCREEN_W2 + num_pages * k_pagelist_w / 2;

	for (int i = 0; i < num_pages; i++)
	{
		int x = x1 + i * k_pagelist_w + k_pagelist_w / 2;

		if ( GetCurrentBook()[i]->isActive() )
			sprite->PaintFrame( k_pagelist_active_frame, x, k_pagelist_y );
		else
			sprite->PaintFrame( k_pagelist_inactive_frame, x, k_pagelist_y );	
	}
}

