void PageManager::SetMenuType( MenuHelp_Types type )
{
	for ( int i = 0; i< m_enemiesBook.size(); i++ )
	{
		m_enemiesBook[i]->SetVisible( false );
	}

	for ( int j = 0; j< m_spellsBook.size(); j++ )
	{
		m_spellsBook[j]->SetVisible( false );
	}

	switch ( type )
	{
	case MenuHelp_NotSet: 
		{
			m_pane = NULL;	
			m_currentBookType = MenuHelp_NotSet;
			return;
		}
		break;
	case MenuHelp_EnemiesBook:
		{
			m_pane = m_enemiesPane;	
			m_currentBookType = MenuHelp_EnemiesBook;
		}
		break;
	case MenuHelp_SpellsBook:
		{
			m_pane = m_spellsPane;
			m_currentBookType = MenuHelp_SpellsBook;
		}
		break;
	default :
		{
			m_pane = NULL;
			GX_ASSERT( false );
		}
		break;
	}

	
	
	for ( int j = 0; j< GetCurrentBook().size(); j++ )
	{
		GetCurrentBook()[j]->SetVisible( true );
	}
	
}
